Code.Terraform:
```hcl
resource "aws_glue_connection" "example" {
  name = "my-jdbc-connection"

  connection_properties = {
    JDBC_CONNECTION_URL = "jdbc:mysql://${aws_db_instance.example.address}:3306/mydb"
    # Reference the secret ARN instead of a plaintext password
    SECRET_ID = aws_secretsmanager_secret.example.arn
  }
}
